/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_ACCOUNT_DEFINITION
   anchor      : HUB_FINANCIAL_ACCOUNT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_FINANCIAL_ACCOUNT_HK
   hashdiff    : SAT_ACCOUNT_DEFINITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 1 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     ACCOUNT_TYPE                           opus_health_legacy_v4  2 writer(s), of which 2 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_FINANCIAL_ACCOUNT|' || (HUB_FINANCIAL_ACCOUNT_BK__MLAC_EMI_PC_LOAN_ACCOUNT_NO))) as HUB_FINANCIAL_ACCOUNT_HK
        , MLAC_EMI_PC_TYPE_OF_LOAN as ACCOUNT_TYPE
        , cast(null as varchar) as ACCOUNT_CATEGORY
        , cast(null as varchar) as CLOSING_DATE
        , 'BA_HCP_PROD_8428_GPG_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8428_gpg_loader') }}
    where (nullif(trim(MLAC_EMI_PC_LOAN_ACCOUNT_NO),'')) is not null
    union all
    select
        md5(upper('HUB_FINANCIAL_ACCOUNT|' || (HUB_FINANCIAL_ACCOUNT_BK__PLC_LOAN_ACC_NO))) as HUB_FINANCIAL_ACCOUNT_HK
        , PLC_TYPE_OF_LOAN as ACCOUNT_TYPE
        , PLC_OTH_TYPE_OF_LOAN as ACCOUNT_CATEGORY
        , PLC_LOAN_END_DATE as CLOSING_DATE
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PLC_LOAN_ACC_NO),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_ACCOUNT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCOUNT_TYPE end) as ACCOUNT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCOUNT_CATEGORY end) as ACCOUNT_CATEGORY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLOSING_DATE end) as CLOSING_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_ACCOUNT_HK
),

hashed as (
    select
        *,
        case when ACCOUNT_TYPE is not null or ACCOUNT_CATEGORY is not null or CLOSING_DATE is not null
                     then md5(upper(coalesce(cast(ACCOUNT_TYPE as varchar), '') || '|' || coalesce(cast(ACCOUNT_CATEGORY as varchar), '') || '|' || coalesce(cast(CLOSING_DATE as varchar), '')))
                end as SAT_ACCOUNT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_ACCOUNT_HK is not null
  and SAT_ACCOUNT_DEFINITION_HASHDIFF is not null
